    practice_en: ["Print sizeof(short), sizeof(int), sizeof(long) and sizeof(long long)", "Compute 50000 × 50000 with int and with long long and compare"],
    practice_bn: ["sizeof(short), sizeof(int), sizeof(long) ও sizeof(long long) প্রিন্ট করো", "50000 × 50000 একবার int দিয়ে, একবার long long দিয়ে হিসাব করে তুলনা করো"],
